import { useEffect, useRef } from "react";
import { GameState } from "../constants/enum";

/**
 * 게임 루프를 관리하는 커스텀 훅
 * useRef와 requestAnimationFrame을 사용하여 게임 루프를 구현합니다.
 * requestAnimationFrame은 브라우저의 리페인트 주기에 맞춰 콜백 함수를 호출하므로,
 * 부드러운 애니메이션과 효율적인 렌더링이 가능합니다.
 * @param callback 매 프레임마다 호출되는 콜백 함수
 * @returns void
 */

export default function useGameLoop(
  callback: () => void,
  playState: GameState,
) {
  const requestRef = useRef<number>(0);
  const animate = () => {
    callback();
    requestRef.current = requestAnimationFrame(animate);
  };
  useEffect(() => {
    if (playState === GameState.PLAYING) {
      requestRef.current = requestAnimationFrame(animate);
    }
    return () => cancelAnimationFrame(requestRef.current);
  }, [callback, playState]);
}
